def _format_hash(checksum):
    if isinstance(checksum, dict):
        return "{} -> {}".format(checksum["old"], checksum["new"])
    return checksum


def _show_diff(diff, show_hash=False):
    from dvc.utils.diff import table

    rows = []
    for change, entries in diff.items():
        for entry in entries:
            row = [entry["path"]]
            if show_hash:
                checksum = entry.get("hash")
                row.append(_format_hash(checksum) if checksum else "")
            row.append(change)
            rows.append(row)

    header = ["Path"]
    if show_hash:
        header.append("Hash")
    header.append("Change")
    return table(header, rows)
```

